const reglas = $('Get_Reglas').all()[0].json;

function horaAMinutos(hora) {
  const [h, m] = hora.split(':').map(Number);
  return h * 60 + m;
}

function minutosAHora(minutos) {
  const h = Math.floor(minutos / 60);
  const m = minutos % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

const turnosTransformados = [];

for (const item of $input.all()) {
  const turno = item.json;
  const regla = reglas.find(r => r.Id_Calendario === turno.Id_Calendario);

  if (!regla) {
    turnosTransformados.push(turno);
    continue;
  }

  const TIEMPO_RECEPCION = regla.Tiempo_Recepcion || 15;
  const TIEMPO_ENTREGA = regla.Tiempo_Entrega || 15;
  const TIEMPO_LAVADO = regla.Tiempo_Lavado || 30;
  const DURACION_ALMUERZO = regla.Duracion_Almuerzo || 60;

  const almuerzo_inicio_min = horaAMinutos(regla.Almuerzo_Inicio || "12:00");
  const almuerzo_fin_min = horaAMinutos(regla.Almuerzo_Fin || "13:00");

  const inicio_min = horaAMinutos(turno.inicio);
  const fin_min = horaAMinutos(turno.final);

  const inicio_cliente_min = inicio_min - TIEMPO_RECEPCION;
  let fin_cliente_min = fin_min + TIEMPO_LAVADO + TIEMPO_ENTREGA;

  if (inicio_min < almuerzo_fin_min && fin_min > almuerzo_inicio_min) {
    fin_cliente_min += DURACION_ALMUERZO;
  }

  turnosTransformados.push({
    dia: turno.dia,
    inicio: minutosAHora(inicio_cliente_min),
    final: minutosAHora(fin_cliente_min),
    Id_Calendario: turno.Id_Calendario
  });
}

return turnosTransformados.map(t => ({ json: t }));
